'use strict';
const SEASONS=[{name:'Wiosna',icon:'❀',food:1.15,color:'#7b9865'},{name:'Lato',icon:'☀',food:1.3,color:'#87965b'},{name:'Jesień',icon:'❧',food:1.5,color:'#9b8955'},{name:'Zima',icon:'❄',food:.25,color:'#c0cbb7'}];
function initFrontier(){state.frontier??={};const f=state.frontier;f.elapsed=Math.max(0,Number(f.elapsed)||0);f.diplomacyClock??=0;f.eventIndex??=0;f.pacts??=[];f.marches??=[];f.history??=[];f.steel=Math.max(0,Math.min(3,Number(f.steel)||0));f.cold??=false;state.iron=Math.max(0,Number(state.iron)||0);state.goldOre=Math.max(0,Number(state.goldOre)||0);for(const t of state.towns){t.marketStock??={};t.marketStock.iron??=30;t.marketStock.goldOre??=20}f.nextMarch??=1}
function seasonIndex(){if(state.campaign?.stage==='desert')return 1;return Math.floor((state.frontier?.elapsed||0)/180)%4}
function seasonInfo(){return SEASONS[seasonIndex()]}
function seasonRemaining(){return Math.ceil(180-(state.frontier.elapsed%180))}
function seasonalTerrain(t,r){if(state.campaign?.stage==='desert')return t==='grass'?(r>.5?'#c9a568':'#d3b174'):null;return t==='grass'?(r>.5?seasonInfo().color:['#718957','#7b8b50','#8a7b4b','#b5c2ae'][seasonIndex()]):null}
function winterFoodCost(){return Math.max(1,Math.ceil(population()/3))}
function winterWoodCost(){return Math.max(1,Math.ceil(population()/5))}
function frontierProduction(){const f=state.frontier;let iron=0,ore=0;for(const b of state.buildings){const seconds=workLedger.get(tileKey(b.x,b.y))||0;if(b.type==='zelazo')iron+=seconds/12*4;if(b.type==='zloto')ore+=seconds/12*2}state.iron=Math.min(capacity(),state.iron+iron);state.goldOre=Math.min(capacity(),state.goldOre+ore);f.cold=false;if(seasonIndex()===3&&state.settled){const wood=winterWoodCost(),food=winterFoodCost();f.cold=state.wood<wood;state.wood=Math.max(0,state.wood-wood);state.food=Math.max(0,state.food-food);if(f.cold)say('Zima: brakuje drewna na ogrzewanie. Zbiory spadły o połowę.')}return seasonInfo().food*(f.cold?.5:1)}
function smeltGold(){if(!ownCount('targ')&&!ownCount('kuznia')){say('Przetop wymaga targu lub kuźni.');return false}if(state.goldOre<5){say('Przetop wymaga 5 rudy złota.');return false}state.goldOre-=5;state.gold+=15;save();ui();renderFrontier();return true}
function forgeSteel(){const f=state.frontier,n=f.steel+1;if(!ownCount('kuznia')||n>3||state.iron<10*n||state.gold<20*n){say('Wymagana kuźnia, '+10*n+' żelaza i '+20*n+' monet. Maksymalnie 3 poziomy.');return false}state.iron-=10*n;state.gold-=20*n;f.steel=n;warLog('Stalowa broń: poziom '+n+'.');save();ui();renderFrontier();return true}
function ownSoldierActors(){const w=state.war,k=state.kingdom;return [...(w.guards||[]),...(w.patrols||[]).flatMap(p=>p.units),...(w.expedition?.army||[]),...(k?.fleet||[]).flatMap(s=>s.passengers),...(k?.caravans||[]).flatMap(c=>c.escorts)]}
function promoteHero(uid,role){if(!['hero','commander'].includes(role))return false;const u=state.war.guards.find(u=>u.uid===uid);if(!u||u.hero||!ownCount('werbunek'))return false;if(ownSoldierActors().filter(u=>u.hero).length>=3){say('Możesz utrzymywać 3 bohaterów lub dowódców.');return false}if(state.gold<80||state.food<30){say('Awans kosztuje 80 monet i 30 żywności.');return false}state.gold-=80;state.food-=30;u.hero={role,name:role==='commander'?'Dowódca':'Bohater',level:1,xp:0};warLog('Awansowano żołnierza: '+u.hero.name+'.');save();ui();renderFrontier();return true}
function gainHeroXP(u,amount){if(!u?.hero||amount<=0)return;const h=u.hero;h.xp+=amount;while(h.level<5&&h.xp>=h.level*20){h.xp-=h.level*20;h.level++;warLog(h.name+' osiągnął poziom '+h.level+'!')}if(h.level===5)h.xp=0}
function activeFrontierTroops(){return [...state.war.guards,...state.war.patrols.flatMap(p=>p.units),...(state.kingdom?.caravans||[]).flatMap(c=>c.escorts)]}
function recordHeroHit(u){gainHeroXP(u,1);if(!ownSoldierActors().includes(u))return;for(const a of activeFrontierTroops())if(a!==u&&a.hero?.role==='commander'&&Math.hypot(a.x-u.x,a.y-u.y)<=6*T)gainHeroXP(a,.25)}
function commanderBonus(u){if(!ownSoldierActors().includes(u))return 0;return activeFrontierTroops().reduce((bonus,a)=>a.hero?.role==='commander'&&Math.hypot(a.x-u.x,a.y-u.y)<=6*T?Math.max(bonus,a.hero.level*.25):bonus,0)}
function frontierSoldierBonus(u){if(!ownSoldierActors().includes(u))return 0;return (state.frontier?.steel||0)*.5+(u.hero?.role==='hero'?u.hero.level:0)+commanderBonus(u)}
function frontierArmyBonus(count,army){const units=(army||[]).slice(0,count),commander=Math.max(0,...units.filter(u=>u.hero?.role==='commander').map(u=>u.hero.level));return count*(state.frontier?.steel||0)+units.reduce((n,u)=>n+(u.hero?.role==='hero'?u.hero.level*2:0),0)+count*commander*.5}
function pactKey(a,b){return [a.id,b.id].sort().join('|')}
function eligibleDiplomacyTown(t){return t.relation!=='conquered'}
function frontierLog(message,a,b){const f=state.frontier;f.history.unshift({text:message,a:a.id,b:b.id});f.history=f.history.slice(0,30);if(a.discovered&&b.discovered)warLog(message)}
function neighborDiplomacy(){const f=state.frontier,towns=state.towns.filter(eligibleDiplomacyTown);if(towns.length<2)return;const a=towns[f.eventIndex%towns.length];f.eventIndex++;const neighbors=towns.filter(t=>t!==a).sort((x,y)=>Math.hypot(x.x-a.x,x.y-a.y)-Math.hypot(y.x-a.x,y.y-a.y));const b=neighbors[(Math.floor(f.eventIndex/towns.length))%Math.min(3,neighbors.length)],key=pactKey(a,b);let pact=f.pacts.find(p=>p.key===key);if(pact?.truce>0)return;if(!pact){pact={key,a:a.id,b:b.id,status:f.eventIndex%3===0?'allied':'war',clock:0,truce:0};f.pacts.push(pact);frontierLog(a.name+(pact.status==='war'?' wypowiada wojnę osadzie ':' zawiera sojusz z ')+b.name+'.',a,b)}else if(pact.status==='war'&&(pact.age||0)>=180){pact.status='peace';pact.truce=180;frontierLog(a.name+' i '+b.name+' zawierają pokój.',a,b)}else if(pact.status==='peace'){pact.status='allied';frontierLog(a.name+' i '+b.name+' zawierają sojusz.',a,b)}
}
function launchNeighborMarch(pact){const f=state.frontier,a=state.towns.find(t=>t.id===pact.a),b=state.towns.find(t=>t.id===pact.b);if(!a||!b||!eligibleDiplomacyTown(a)||!eligibleDiplomacyTown(b)||f.marches.some(m=>m.key===pact.key))return false;const route=campaignRoute(a,b,true);if(!route)return false;const allies=f.pacts.filter(p=>p.status==='allied'&&(p.a===a.id||p.b===a.id)).length;f.marches.push({id:'neighbor-'+f.nextMarch++,key:pact.key,from:a.id,to:b.id,route,progress:0,naval:true,power:Math.max(4,Math.round(a.power*.35)+Math.min(3,allies)*2)});return true}
function resolveNeighborMarch(m){const a=state.towns.find(t=>t.id===m.from),b=state.towns.find(t=>t.id===m.to);if(!a||!b||!eligibleDiplomacyTown(a)||!eligibleDiplomacyTown(b))return;const damage=Math.min(Math.max(0,b.power-6),Math.max(1,Math.round(m.power*.4)));b.power-=damage;a.power=Math.min(100,a.power+1);frontierLog(a.name+' atakuje '+b.name+'. Obrona celu: −'+damage+'.',a,b)}
function mediatePact(key){const p=state.frontier.pacts.find(p=>p.key===key),a=state.towns.find(t=>t.id===p?.a),b=state.towns.find(t=>t.id===p?.b);if(!p||p.status!=='war'||!a?.discovered||!b?.discovered||state.gold<40)return false;state.gold-=40;p.status='peace';p.truce=180;p.clock=0;state.frontier.marches=state.frontier.marches.filter(m=>m.key!==key);frontierLog('Twoje poselstwo kończy wojnę: '+a.name+' i '+b.name+'. Rozejm 3 minuty.',a,b);save();ui();renderFrontier();return true}
let frontierUITime=0;
function updateFrontier(dt){const f=state.frontier,previous=seasonIndex();f.elapsed+=dt;if(previous!==seasonIndex()){warLog('Nadeszła '+seasonInfo().name.toLowerCase()+'.');save();ui()}f.diplomacyClock+=dt;for(const p of f.pacts){p.clock+=dt;p.age=(p.age||0)+dt;p.truce=Math.max(0,(p.truce||0)-dt);const a=state.towns.find(t=>t.id===p.a),b=state.towns.find(t=>t.id===p.b);if(!a||!b||!eligibleDiplomacyTown(a)||!eligibleDiplomacyTown(b)){p.status='peace';continue}if(p.status==='war'&&p.age>=180){p.status='peace';p.truce=180;p.age=0;frontierLog(a.name+' i '+b.name+' zawierają pokój.',a,b)}if(p.status==='war'&&p.clock>=60){p.clock=0;launchNeighborMarch(p)}}if(state.settled&&f.diplomacyClock>=45){f.diplomacyClock%=45;neighborDiplomacy();save()}for(const m of f.marches){const p=f.pacts.find(p=>p.key===m.key),a=state.towns.find(t=>t.id===m.from),b=state.towns.find(t=>t.id===m.to);if(p?.status!=='war'||!a||!b||!eligibleDiplomacyTown(a)||!eligibleDiplomacyTown(b)){m.done=true;continue}advanceCampaign(m,dt,2.4);if(m.progress>=m.route.length-1){resolveNeighborMarch(m);m.done=true;save()}}f.marches=f.marches.filter(m=>!m.done);frontierUITime+=dt;if(frontierUITime>=1){frontierUITime=0;renderSeasonBadge();renderFrontier()}}
function drawFrontierWorld(){for(const m of state.frontier.marches){const p=routePosition(m);if(!seen.has(tileKey(Math.floor(p.x/T),Math.floor(p.y/T))))continue;drawCampaignForce(m,Math.ceil(m.power/4),(x,y)=>seen.has(tileKey(Math.floor(x/T),Math.floor(y/T))));ctx.fillStyle='#d7ad83';ctx.font='10px system-ui';ctx.fillText('WOJNA SĄSIADÓW',p.x-40,p.y-53)}}
function drawMine(b,x,y){if(!['zelazo','zloto'].includes(b.type))return false;polygon([[x-24,y+10],[x-21,y-15],[x,y-38],[x+22,y-15],[x+25,y+10]],'#777e71');ctx.fillStyle='#25382f';ctx.beginPath();ctx.arc(x,y-2,13,Math.PI,0);ctx.fill();ctx.fillRect(x-13,y-2,26,12);ctx.fillStyle='#8e704a';ctx.fillRect(x-18,y-20,5,31);ctx.fillRect(x+13,y-20,5,31);ctx.fillRect(x-18,y-23,36,6);ctx.fillStyle=b.type==='zloto'?'#e6bf56':'#a4b8c2';for(let i=0;i<4;i++)ctx.fillRect(x-19+i*11,y-28-(i%2)*8,5,5);return true}
const battleActorBeforeFrontier=drawBattleActor;drawBattleActor=function(u,color){battleActorBeforeFrontier(u,color);if(u.hero){ctx.fillStyle='#ffe29b';ctx.font='bold 10px system-ui';ctx.fillText((u.hero.role==='commander'?'⚑':'★')+' '+u.hero.name+' '+u.hero.level,u.x-30,u.y-63)}};
const resolveBeforeFrontier=resolveExpedition;resolveExpedition=function(){const e=state.war.expedition;if(e?.army)for(const u of e.army)gainHeroXP(u,8);resolveBeforeFrontier()};
function renderSeasonBadge(){$('seasonBadge').textContent=seasonInfo().icon+' '+seasonInfo().name+' · '+seasonRemaining()+' s';$('seasonBadge').title='Rok '+(Math.floor(state.frontier.elapsed/720)+1)+' · Każda pora roku trwa 3 minuty gry.'}
let frontierTab='seasons';
function frontierSeasonUI(){const f=state.frontier;return `<h3>${seasonInfo().icon} ${seasonInfo().name} · rok ${Math.floor(f.elapsed/720)+1}</h3><p>Zmiana pory roku za ${seasonRemaining()} s. Kalendarz działa razem z pauzą i tempem gry.</p><div class="season-grid">${SEASONS.map((s,i)=>`<div class="${i===seasonIndex()?'active':''}"><b>${s.icon} ${s.name}</b><small>Zbiory ×${s.food.toLocaleString('pl')}</small></div>`).join('')}</div><h3>Przygotuj się na zimę</h3><p>Zimą co 12 sekund osada zużywa ${winterWoodCost()} drewna na ogrzewanie i ${winterFoodCost()} żywności. Potrzeby rosną wraz z liczbą mieszkańców. Brak opału zmniejsza zbiory o kolejne 50%. Mieszkańcy nie umierają z głodu.</p><div class="war-summary"><div><strong>${Math.floor(state.wood)}</strong><small>DREWNO</small></div><div><strong>${Math.floor(state.food)}</strong><small>ŻYWNOŚĆ</small></div></div><p>${seasonIndex()===3?'❄ Zima trwa. '+(f.cold?'Brakuje opału!':'Zadbaj o stałe dostawy drewna.'):'Na pełną zimę odłóż co najmniej '+winterWoodCost()*15+' drewna i '+winterFoodCost()*15+' żywności, oprócz kosztów wojska.'}</p>`}
function frontierMinesUI(){return `<h3>⛏ Żelazo i złoto</h3><div class="war-summary"><div><strong>${Math.floor(state.iron)}</strong><small>ŻELAZO</small></div><div><strong>${Math.floor(state.goldOre)}</strong><small>RUDA ZŁOTA</small></div></div><p>Kopalnię stawiaj na oczyszczonym lądzie lub skale. Każda zatrudnia 1 wolnego mieszkańca, który musi dojść do pracy. Żelazo: +4 / 12 s pracy. Ruda złota: +2 / 12 s pracy. Składy zwiększają pojemność każdego surowca.</p><div class="war-actions"><button data-frontier="build" data-value="zelazo">Buduj kopalnię żelaza · 65 🪵 20 ◆</button><button data-frontier="build" data-value="zloto">Buduj kopalnię złota · 80 🪵 30 ◆</button></div><h3>Stalowa broń · ${state.frontier.steel}/3</h3><p>Każdy poziom dodaje +0,5 obrażeń i +1 siły wyprawy każdemu własnemu żołnierzowi. Potrzebna kuźnia.</p><button data-frontier="steel" ${state.frontier.steel>=3?'disabled':''}>${state.frontier.steel>=3?'Maksymalny poziom':'Ulepsz · '+10*(state.frontier.steel+1)+' żelaza · '+20*(state.frontier.steel+1)+' monet'}</button><h3>Przetapianie i handel</h3><p>Targ lub kuźnia pozwalają przetopić 5 rudy złota w 15 monet. Żelazo i rudę można też kupować i sprzedawać u pokojowych, odkrytych sąsiadów.</p><button data-frontier="smelt" ${state.goldOre<5?'disabled':''}>Przetop 5 rudy → 15 monet</button>`}
function frontierHeroesUI(){const heroes=ownSoldierActors().filter(u=>u.hero);return `<h3>★ Bohaterowie i dowódcy · ${heroes.length}/3</h3><p>Awansuj istniejącego żołnierza garnizonu w biurze werbunkowym: 80 monet i 30 żywności. Nadal zajmuje to samo miejsce w wojsku. Bohater zadaje +1 obrażeń i ma +2 siły wyprawy na poziom. Dowódca dodaje własnym pobliskim żołnierzom +0,25 obrażeń na poziom w promieniu 6 pól, a wyprawie +0,5 siły na żołnierza. Premie dowódców nie sumują się.</p><p>Doświadczenie: 1 za cios, dowódca także 0,25 za cios pobliskiego sojusznika; 8 za bitwę wyprawy. Maksymalny poziom: 5. Bohater może polec i leczy się tak jak pozostali.</p>${heroes.map(u=>`<section class="town-card"><b>${u.hero.role==='commander'?'⚑':'★'} ${u.hero.name} · poziom ${u.hero.level}</b><p>${u.hero.level===5?'Maksymalny poziom':Math.floor(u.hero.xp)+' / '+u.hero.level*20+' doświadczenia'} · ${Math.ceil(u.hp??8)}/8 PŻ · ${state.war.guards.includes(u)?'garnizon':'poza garnizonem'}</p></section>`).join('')}${state.war.guards.filter(u=>!u.hero).map((u,i)=>`<div class="town-card"><b>${u.kind==='crossbow'?'Kusznik':u.kind==='shield'?'Tarczownik':u.kind==='archer'?'Łucznik':u.kind==='cavalry'?'Jeździec':'Żołnierz'} ${i+1}</b><div class="war-actions"><button data-frontier="promote" data-value="${u.uid}" data-role="hero" ${heroes.length>=3?'disabled':''}>Awansuj na bohatera</button><button data-frontier="promote" data-value="${u.uid}" data-role="commander" ${heroes.length>=3?'disabled':''}>Awansuj na dowódcę</button></div></div>`).join('')||'<p>Brak wolnych kandydatów w garnizonie. Zwerbuj żołnierzy w biurze.</p>'}`}
function frontierDiplomacyUI(){const f=state.frontier,visible=p=>state.towns.some(t=>t.id===p.a&&t.discovered)&&state.towns.some(t=>t.id===p.b&&t.discovered),name=id=>state.towns.find(t=>t.id===id)?.name||'Osada';return `<h3>⚖ Wojny i sojusze sąsiadów</h3><p>Co 45 sekund sąsiedzi podejmują decyzje. Wojujące osady wysyłają oddziały co minutę; bitwy osłabiają obronę celu. Sojusze wzmacniają ich wyprawy. Relacje sąsiadów nie zmieniają Twoich własnych traktatów. Twoje podbite osady są wyłączone z tych wojen.</p><p>Odkryj obie osady, aby poznać ich relację. Poselstwo za 40 monet kończy ich wojnę i daje 3 minuty rozejmu.</p>${f.pacts.filter(visible).map(p=>`<section class="town-card"><b>${name(p.a)} ↔ ${name(p.b)}</b><p>${{war:'⚔ Wojna',allied:'☘ Sojusz',peace:'⚖ Pokój'}[p.status]}${p.truce>0?' · rozejm '+Math.ceil(p.truce)+' s':''}</p>${p.status==='war'?'<button data-frontier="mediate" data-value="'+p.key+'">Wyślij poselstwo · 40 monet</button>':''}</section>`).join('')||'<p>Nie znasz jeszcze traktatów sąsiadów. Odkrywaj osady na mapie.</p>'}<h3>Wieści z pogranicza</h3>${f.history.filter(visible).slice(0,12).map(h=>'<p class="war-notice">'+h.text+'</p>').join('')||'<p>Wieści pojawią się po odkryciu sąsiadów.</p>'}`}
function renderFrontier(){if($('frontierPanel').classList.contains('hidden'))return;$('frontierContent').innerHTML=`<nav class="strategy-tabs">${[['seasons','Pory roku'],['diplomacy','Dyplomacja'],['heroes','Bohaterowie'],['mines','Kopalnie']].map(([k,n])=>'<button data-frontier="tab" data-value="'+k+'" class="'+(frontierTab===k?'active':'')+'">'+n+'</button>').join('')}</nav>`+({seasons:frontierSeasonUI,diplomacy:frontierDiplomacyUI,heroes:frontierHeroesUI,mines:frontierMinesUI}[frontierTab])()}
function openFrontier(tab='seasons'){frontierTab=tab;for(const id of ['warPanel','strategyPanel','kingdomPanel'])$(id).classList.add('hidden');$('frontierPanel').classList.remove('hidden');renderFrontier()}
$('frontierOpen').onclick=()=>openFrontier();$('seasonBadge').onclick=()=>openFrontier('seasons');$('frontierClose').onclick=()=>$('frontierPanel').classList.add('hidden');$('frontierPanel').onclick=e=>{const b=e.target.closest('button[data-frontier]');if(!b||b.disabled)return;const v=b.dataset.value;switch(b.dataset.frontier){case 'tab':frontierTab=v;break;case 'build':$('frontierPanel').classList.add('hidden');setMode(v);say(defs.find(d=>d[0]===v)[5]);break;case 'promote':promoteHero(v,b.dataset.role);break;case 'steel':forgeSteel();break;case 'smelt':smeltGold();break;case 'mediate':mediatePact(v);break}renderFrontier()};
initFrontier();renderSeasonBadge();ui();

const warOpenBeforeFrontier=$('warOpen').onclick;$('warOpen').onclick=e=>{$('frontierPanel').classList.add('hidden');warOpenBeforeFrontier(e)};const strategyOpenBeforeFrontier=$('strategyOpen').onclick;$('strategyOpen').onclick=e=>{$('frontierPanel').classList.add('hidden');strategyOpenBeforeFrontier(e)};window.addEventListener('keydown',e=>{if(e.key==='Escape')$('frontierPanel').classList.add('hidden')});
